prompt:
**Description:** The program must print a[0] * a[1] (values up to 10^5), but
sometimes prints nonsense. Find and fix the bug.

**Broken code:**
```cpp
void solve(std::istream& in, std::ostream& out) {
    int a, b; in >> a >> b;
    int p = a * b;
    out << p;
}
```

**Input:** One line: a b (|a|, |b| <= 100000).
**Output:** One integer — the product.

**Example:** `300 400` -> `120000`.

boilerplate:
#include <bits/stdc++.h>
using namespace std;

void solve(istream& in, ostream& out) {
    // Đọc dữ liệu từ `in` (dùng như cin), in kết quả ra `out` (dùng như cout).
    // (Ghép bài thực tế: chương trình thi đọc từ bàn phím / tệp — ở đây
    //  để chấm tự động, dữ liệu vào/ra đi qua hai luồng này.)
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}

tests.code:
std::istringstream in("300 400\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("120000\n"));

std::istringstream in("-3 7\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("-21\n"));

std::istringstream in("100000 100000\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("10000000000\n"));

std::istringstream in("-100000 99999\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("-9999900000\n"));

std::istringstream in("0 99999\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("0\n"));
